% Gas cost model of the contracts, shared by all of them.
%
% Included in every contract analyzed by CiaoPP (stage ciaopp_cost of the
% pipeline): `:- include(cost_model)`. To change the cost model, change it
% here only.
%
% It holds:
%   1. the resource and the default costs: only the blockchain primitives
%      cost gas, everything else is free (model of the CiaoPP cost tests
%      of the IMDEA, interreg-imdea/benchmarks/ciaopp_cost_tests);
%   2. the types of the tables the primitives scan;
%   3. the primitives themselves (code generated by the pipeline, identical
%      in every contract that uses them; the pipeline removes them from the
%      contract before including this file), each with a trusted gas cost of
%      one unit per table entry scanned.
% A contract may use only some of the primitives: the others are defined
% here anyway, and are simply never called.

% --- 1. Resource and default costs ---

:- resource gas.

:- head_cost(ub, gas, 0).
:- head_cost(lb, gas, 0).

:- literal_cost(ub, gas, 0).
:- literal_cost(lb, gas, 0).

:- trust_default + cost(ub, gas, 0).

% --- 2. Tables ---

% Coin balances: bal(Address, Amount).
:- regtype balances/1.
balances([]).
balances([X|T]) :- balpair(X), balances(T).

:- regtype balpair/1.
balpair(bal(A, B)) :- atm(A), int(B).

% Token balances: tb(Address, Amount).
:- regtype tok_balances/1.
tok_balances([]).
tok_balances([X|T]) :- tok_balpair(X), tok_balances(T).

:- regtype tok_balpair/1.
tok_balpair(tb(A, B)) :- atm(A), int(B).

% Token allowances: al(Owner, Spender, Amount).
:- regtype allowances/1.
allowances([]).
allowances([X|T]) :- allowance(X), allowances(T).

:- regtype allowance/1.
allowance(al(A, B, C)) :- atm(A), atm(B), int(C).

% NFT owners: t_o(TokenId, Owner).
:- regtype nft_owners/1.
nft_owners([]).
nft_owners([X|T]) :- nft_owner(X), nft_owners(T).

:- regtype nft_owner/1.
nft_owner(t_o(A, B)) :- gnd(A), atm(B).

% NFT balances: n_b(Owner, Count).
:- regtype nft_balances/1.
nft_balances([]).
nft_balances([X|T]) :- nft_balpair(X), nft_balances(T).

:- regtype nft_balpair/1.
nft_balpair(n_b(A, B)) :- atm(A), int(B).

% NFT approvals: app(TokenId, Approved).
:- regtype nft_approvals/1.
nft_approvals([]).
nft_approvals([X|T]) :- nft_approval(X), nft_approvals(T).

:- regtype nft_approval/1.
nft_approval(app(A, B)) :- gnd(A), atm(B).

% NFT operator approvals: op(Owner, Operator, Flag).
:- regtype nft_operators/1.
nft_operators([]).
nft_operators([X|T]) :- nft_operator(X), nft_operators(T).

:- regtype nft_operator/1.
nft_operator(op(A, B, C)) :- atm(A), atm(B), gnd(C).

% --- 3. Primitives ---

% Coins. get_bal(Addr, B, Bal): Bal is the amount of the last
% bal(Addr, _) of B, or 0.
:- trust pred get_bal(Addr, B, Bal)
   + ( not_fails, is_det, cost(lb, gas, length(B)), cost(ub, gas, length(B)) ).
get_bal(A, B, C) :-
    get_bal_loop(B, A, 0, C).
get_bal_loop([], _, A, A).
get_bal_loop([bal(A, B)|C], D, E, F) :-
    get_bal_cond(A, D, G, B, E),
    get_bal_loop(C, D, G, F).
get_bal_cond(A, A, B, B, _) :-
    !.
get_bal_cond(_, _, A, _, A).

% set_bal(Addr, NewVal, B_in, B_out): every bal(Addr, _) of B_in gets
% NewVal. It neither adds nor removes entries, so B_out has the length of
% B_in (stated in the trust: the type domain cannot see it).
:- trust pred set_bal(Addr, NewVal, B_in, B_out)
   => ( balances(B_out), size(lb, B_out, length(B_in)), size(ub, B_out, length(B_in)) )
   + ( not_fails, is_det, cost(lb, gas, length(B_in)), cost(ub, gas, length(B_in)) ).
set_bal(A, B, C, D) :-
    set_bal_loop(C, A, B, D).
set_bal_loop([], _, _, []).
set_bal_loop([bal(A, B)|C], D, E, F) :-
    set_bal_cond(A, D, F, E, G, B),
    set_bal_loop(C, D, E, G).
set_bal_cond(A, A, [bal(A, B)|C], B, C, _) :-
    !.
set_bal_cond(A, _, [bal(A, B)|C], _, C, B).

% transfer(From, To, Amount, B_in, B_out): two get_bal and two set_bal.
:- trust pred transfer(From, To, Amount, B_in, B_out)
   => ( balances(B_out), size(lb, B_out, length(B_in)), size(ub, B_out, length(B_in)) )
   + ( not_fails, is_det, cost(lb, gas, 4*length(B_in)), cost(ub, gas, 4*length(B_in)) ).
transfer(A, B, C, D, E) :-
    get_bal(A, D, F),
    G is F,
    H is G-C,
    I is H,
    set_bal(A, I, D, J),
    get_bal(B, J, K),
    L is K,
    M is L+C,
    N is M,
    set_bal(B, N, J, E).

% Tokens. get_tok_bal(Addr, TB, Bal): amount of the first tb(Addr, _).
:- trust pred get_tok_bal(Addr, TB, Bal)
   + ( not_fails, is_det, cost(lb, gas, length(TB)), cost(ub, gas, length(TB)) ).
get_tok_bal(A, B, C) :-
    get_tok_bal_loop(B, A, 0, C).
get_tok_bal_loop([], _, A, A).
get_tok_bal_loop([tb(A, B)|C], D, E, F) :-
    get_tok_bal_cond(A, D, E, G, B),
    get_tok_bal_loop(C, D, G, F).
get_tok_bal_cond(A, A, 0, B, B) :-
    !.
get_tok_bal_cond(_, _, A, A, _).

% get_allow(Owner, Spender, AL, Amount): amount of the first
% al(Owner, Spender, _).
:- trust pred get_allow(Owner, Spender, AL, Amount)
   + ( not_fails, is_det, cost(lb, gas, length(AL)), cost(ub, gas, length(AL)) ).
get_allow(A, B, C, D) :-
    get_allow_loop(C, A, B, 0, D).
get_allow_loop([], _, _, A, A).
get_allow_loop([al(A, B, C)|D], E, F, G, H) :-
    get_allow_cond(A, E, B, F, G, I, C),
    get_allow_loop(D, E, F, I, H).
get_allow_cond(A, A, B, B, 0, C, C) :-
    !.
get_allow_cond(_, _, _, _, A, A, _).

% NFTs. get_owner(TokenId, TO, Owner): owner of the first t_o(TokenId, _),
% or null.
:- trust pred get_owner(Tok, TO, Owner)
   + ( not_fails, is_det, cost(lb, gas, length(TO)), cost(ub, gas, length(TO)) ).
get_owner(A, B, C) :-
    get_owner_loop(B, A, null, C).
get_owner_loop([], _, A, A).
get_owner_loop([t_o(A, B)|C], D, E, F) :-
    get_owner_cond(A, D, E, G, B),
    get_owner_loop(C, D, G, F).
get_owner_cond(A, A, null, B, B) :-
    !.
get_owner_cond(_, _, A, A, _).

% get_nft_bal(Owner, NB, Count): count of the first n_b(Owner, _), or 0.
:- trust pred get_nft_bal(Owner, NB, Count)
   + ( not_fails, is_det, cost(lb, gas, length(NB)), cost(ub, gas, length(NB)) ).
get_nft_bal(A, B, C) :-
    get_nft_bal_loop(B, A, 0, C).
get_nft_bal_loop([], _, A, A).
get_nft_bal_loop([n_b(A, B)|C], D, E, F) :-
    get_nft_bal_cond(A, D, E, G, B),
    get_nft_bal_loop(C, D, G, F).
get_nft_bal_cond(A, A, 0, B, B) :-
    !.
get_nft_bal_cond(_, _, A, A, _).

% get_appr(TokenId, AP, Approved): approved address of the first
% app(TokenId, _), or null.
:- trust pred get_appr(Tok, AP, Approved)
   + ( not_fails, is_det, cost(lb, gas, length(AP)), cost(ub, gas, length(AP)) ).
get_appr(A, B, C) :-
    get_appr_loop(B, A, null, C).
get_appr_loop([], _, A, A).
get_appr_loop([app(A, B)|C], D, E, F) :-
    get_appr_cond(A, D, E, G, B),
    get_appr_loop(C, D, G, F).
get_appr_cond(A, A, null, B, B) :-
    !.
get_appr_cond(_, _, A, A, _).

% get_op_appr(Owner, Operator, OP, Flag): flag of the first
% op(Owner, Operator, _), or 0.
:- trust pred get_op_appr(Owner, Operator, OP, Flag)
   + ( not_fails, is_det, cost(lb, gas, length(OP)), cost(ub, gas, length(OP)) ).
get_op_appr(A, B, C, D) :-
    get_op_appr_loop(C, B, A, 0, D).
get_op_appr_loop([], _, _, A, A).
get_op_appr_loop([op(A, B, C)|D], E, F, G, H) :-
    get_op_appr_cond(A, F, B, E, G, I, C),
    get_op_appr_loop(D, E, F, I, H).
get_op_appr_cond(A, A, B, B, 0, C, C) :-
    !.
get_op_appr_cond(_, _, _, _, A, A, _).
